const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{position:relative;overflow:hidden;color:var(--ink)}\n.q-root{position:absolute;inset:0;box-sizing:border-box;padding:6px;font-size:12px;line-height:1.3;color:var(--ink);overflow:hidden;min-width:0;min-height:0}\n.q-root *{box-sizing:border-box}\n.q-root button,.q-root input{font:inherit}\n.card[data-size=\"6x3\"] .q-root,.card[data-size=\"3x6\"] .q-root,.card[data-size=\"6x6\"] .q-root{padding:8px;font-size:13px}\n.q-panel{background:var(--panel-paper);border:1px solid var(--line);border-radius:12px;min-width:0;min-height:0}\n\n.q-btn{min-height:30px;padding:0 10px;border-radius:9px;border:1px solid var(--line);background:var(--button-paper,var(--panel-paper));color:var(--ink);cursor:pointer;white-space:nowrap}\n.q-btn.q-sm{min-height:26px;padding:0 8px}\n.q-btn.q-pri{background:var(--accent);color:var(--on-accent);border-color:transparent;font-weight:600}\n.q-btn.q-arm{border-color:var(--accent);box-shadow:inset 0 0 0 1px var(--accent);font-weight:700}\n.q-btn:focus-visible,.q-in:focus-visible,.q-row:focus-visible,.q-prow:focus-visible,.q-srow:focus-visible,.q-ib:focus-visible,.q-gb:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n.q-bold{font-weight:700}\n\n/* \u65b9\u6848\u8be6\u60c5\uff1a\u533a\u57df\u7f51\u683c */\n.q-plan{display:grid;grid-template-columns:minmax(0,1fr);grid-template-rows:auto minmax(0,1fr) auto;grid-template-areas:\"hero\" \"items\" \"add\";gap:6px}\n.card[data-size=\"6x3\"] .q-plan{grid-template-columns:142px minmax(0,1fr);grid-template-rows:minmax(0,1fr) auto;grid-template-areas:\"hero items\" \"add items\"}\n.q-main.q-plan{position:relative;padding:0;height:100%}\n.q-hero{grid-area:hero;background:var(--accent);color:var(--on-accent);border-radius:12px;padding:5px 8px 6px;display:flex;flex-direction:column;gap:3px;min-width:0;min-height:0;overflow:hidden}\n.card[data-size=\"3x6\"] .q-hero,.card[data-size=\"6x6\"] .q-hero{padding:8px 10px;gap:5px}\n.q-head{display:flex;align-items:center;gap:4px;min-width:0}\n.q-pname{flex:1;min-width:0;font-weight:700;font-size:13px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.card[data-size=\"6x3\"] .q-pname{white-space:normal;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow-wrap:anywhere}\n.q-ib{flex:none;width:26px;height:26px;padding:0;border-radius:8px;border:0;background:color-mix(in srgb,var(--on-accent) 22%,transparent);color:var(--on-accent);cursor:pointer;line-height:1;font-size:16px}\n.q-menu{display:flex;flex-wrap:wrap;gap:4px;align-items:center;font-size:11px}\n.q-gb{min-height:24px;padding:0 8px;border-radius:7px;border:1px solid var(--on-accent);background:transparent;color:var(--on-accent);cursor:pointer;white-space:nowrap}\n.q-tot{display:flex;flex-wrap:wrap;align-items:baseline;column-gap:6px;min-width:0}\n.q-tlab{font-size:10.5px}\n.q-tamt{font-weight:800;line-height:1.1;font-variant-numeric:tabular-nums;white-space:nowrap}\n.q-tamt.f1{font-size:24px}.q-tamt.f2{font-size:21px}.q-tamt.f3{font-size:18px}.q-tamt.f4{font-size:16px}\n.card[data-size=\"6x3\"] .q-tamt.f1{font-size:22px}.card[data-size=\"6x3\"] .q-tamt.f2{font-size:18px}.card[data-size=\"6x3\"] .q-tamt.f3{font-size:16px}.card[data-size=\"6x3\"] .q-tamt.f4{font-size:14px}\n.card[data-size=\"6x6\"] .q-tamt.f1{font-size:30px}.card[data-size=\"6x6\"] .q-tamt.f2{font-size:27px}.card[data-size=\"6x6\"] .q-tamt.f3{font-size:23px}.card[data-size=\"6x6\"] .q-tamt.f4{font-size:20px}\n.q-subs{display:flex;flex-wrap:wrap;gap:0 10px;font-size:11px}\n.card[data-size=\"3x3\"] .q-subs,.card[data-size=\"6x3\"] .q-subs{display:none}\n\n\n.q-items{grid-area:items;overflow-y:auto;overflow-x:hidden;padding:0 8px 4px;overscroll-behavior:contain}\n.q-sec{position:sticky;top:0;z-index:1;background:var(--panel-paper);display:flex;justify-content:space-between;align-items:baseline;gap:6px;padding:6px 0 3px;font-size:11px;font-weight:600;color:var(--muted);border-bottom:1px solid var(--line)}\n.q-sec b{color:var(--ink);font-variant-numeric:tabular-nums;white-space:nowrap}\n.q-row,.q-prow{display:grid;grid-template-columns:minmax(0,1fr) auto;column-gap:8px;width:100%;text-align:left;background:transparent;border:0;border-bottom:1px solid var(--line);padding:6px 0;color:var(--ink);cursor:pointer}\n.q-rn,.q-pn{overflow-wrap:anywhere;font-weight:600;min-width:0}\n.q-ra,.q-pa{font-weight:700;white-space:nowrap;font-variant-numeric:tabular-nums}\n.q-rm,.q-pm{grid-column:1/-1;color:var(--muted);font-size:11px}\n.q-hint{color:var(--muted);padding:10px 2px;text-align:center;font-size:11.5px}\n.q-add{grid-area:add;display:flex;gap:6px}\n.q-add .q-btn{flex:1;min-width:0;padding:0 4px;border-color:var(--accent);font-weight:600}\n.card[data-size=\"6x3\"] .q-add{flex-direction:column}\n.card[data-size=\"6x3\"] .q-add .q-btn{min-height:28px}\n\n/* \u65b9\u6848\u5217\u8868 */\n.q-list{height:100%;display:grid;grid-template-rows:auto minmax(0,1fr);padding:6px 8px 4px;gap:2px}\n.q-lhead{display:flex;align-items:center;gap:6px;min-width:0}\n.q-lt{flex:1;min-width:0;font-weight:700;font-size:14px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.q-cnt{color:var(--muted);font-size:11px;white-space:nowrap}\n.q-plist{overflow-y:auto;overflow-x:hidden;min-height:0;overscroll-behavior:contain}\n.card[data-size=\"6x3\"] .q-plist{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));column-gap:14px;align-content:start}\n.q-empty{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;text-align:center;color:var(--muted)}\n.q-ebig{font-weight:700;color:var(--ink);font-size:13px}\n\n/* 6x6 \u5de6\u4fa7\u65b9\u6848\u680f */\n.q-split{display:grid;grid-template-columns:118px minmax(0,1fr);gap:6px}\n.q-side{display:flex;flex-direction:column;gap:6px;padding:6px;overflow:hidden;height:100%}\n.q-sh{font-weight:700;font-size:12px;padding:0 2px}\n.q-sl{flex:1;min-height:0;overflow-y:auto;display:flex;flex-direction:column;gap:4px;overscroll-behavior:contain}\n.q-srow{display:flex;flex-direction:column;align-items:flex-start;gap:1px;width:100%;min-width:0;text-align:left;padding:6px 7px;border-radius:9px;border:1px solid transparent;background:transparent;color:var(--ink);cursor:pointer}\n.q-srow[aria-current=\"true\"]{background:var(--soft);border-color:var(--accent)}\n.q-sn{font-weight:600;overflow-wrap:anywhere;max-width:100%}\n.q-sa{font-size:11px;color:var(--muted);font-variant-numeric:tabular-nums}\n.q-main.q-empty{height:100%;padding:12px}\n\n/* \u8868\u5355 */\n.q-fm{height:100%;display:flex;flex-direction:column;gap:6px;padding:6px 8px}\n.q-fh{display:flex;align-items:center;gap:6px;min-width:0}\n.q-ft{flex:1;min-width:0;font-weight:700;font-size:13px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.q-fb{flex:1;min-height:0;overflow-y:auto;display:flex;flex-wrap:wrap;gap:6px 8px;align-content:flex-start;padding:1px}\n.q-fld{display:flex;flex-direction:column;gap:2px;flex:1 1 100%;min-width:0}\n.q-fld.q-half{flex:1 1 0}\n.card[data-size=\"6x3\"] .q-fld.q-nm,.card[data-size=\"6x6\"] .q-fld.q-nm{flex:2 1 0}\n.q-fl{font-size:11px;color:var(--muted)}\n.q-in{width:100%;min-width:0;height:30px;padding:0 8px;border-radius:8px;border:1px solid var(--line);background:var(--paper);color:var(--ink)}\n.q-pv{flex:1 1 100%;display:flex;justify-content:space-between;align-items:baseline;gap:8px;padding:4px 8px;border-radius:8px;background:var(--soft);color:var(--ink)}\n.q-pv b{font-variant-numeric:tabular-nums;white-space:nowrap}\n.q-ferr{flex:1 1 100%;font-size:11px;font-weight:600;color:var(--ink)}\n.q-ferr:empty{display:none}\n.q-ff{display:flex;gap:6px}\n.q-ff .q-grow{flex:1}\n.q-toast{position:absolute;left:10px;right:10px;bottom:10px;z-index:5;padding:6px 8px;border-radius:9px;background:var(--panel-paper);border:1px solid var(--accent);color:var(--ink);font-size:11px;font-weight:600;cursor:pointer}\n";
function r2(n){return Math.round(n*100)/100}
function money(n){
  const c=Math.round((Number(n)||0)*100);
  const a=Math.abs(c);
  const y=Math.floor(a/100),f=a%100;
  let s=String(y).replace(/\B(?=(\d{3})+(?!\d))/g,',');
  if(f)s+='.'+(f<10?'0':'')+f;
  return (c<0?'-':'')+'¥'+s;
}
function hrs(h){return String(r2(Number(h)||0))}
function laborC(x){return Math.round((Number(x.hours)||0)*(Number(x.rate)||0)*100)}
function costC(x){return Math.round((Number(x.amount)||0)*100)}
function sumTotals(p){
  const L=Array.isArray(p.labor)?p.labor:[],C=Array.isArray(p.costs)?p.costs:[];
  let lc=0,h=0,cc=0;
  L.forEach(x=>{lc+=laborC(x);h+=Number(x.hours)||0});
  C.forEach(x=>{cc+=costC(x)});
  return {labor:lc/100,cost:cc/100,total:(lc+cc)/100,hours:r2(h),nl:L.length,nc:C.length};
}
function parseNum(v,max){
  const t=String(v==null?'':v).trim();
  if(t==='')return NaN;
  const n=Number(t);
  if(!Number.isFinite(n)||n<0||n>max)return NaN;
  return n;
}
function fitCls(s){const n=s.length;return n<=8?'f1':n<=10?'f2':n<=12?'f3':'f4'}

function mount(ctx){
  const {root,el,state,ui,commit,redraw,uid,size}=ctx;
  const plans=Array.isArray(state&&state.plans)?state.plans:[];
  const big=size==='6x6';
  const K=(...a)=>a.filter(Boolean);
  const find=id=>plans.find(p=>p.id===id);
  const go=patch=>{Object.assign(ui,patch);redraw()};
  const mapPlans=(s,fn)=>Object.assign({},s,{plans:(Array.isArray(s&&s.plans)?s.plans:[]).map(fn)});
  let busy=false;
  function run(fn,patch){
    if(busy)return null;
    busy=true;
    return commit(fn,Object.assign({},ui,patch,{err:''})).then(r=>{busy=false;return r}).catch(()=>{busy=false;go({err:'保存失败，已保留原数据，请重试。'});return false});
  }
  function openPlan(id){go({view:'plan',planId:id,menu:false,confirm:false,err:''})}
  function toList(){go({view:'list',menu:false,confirm:false,err:''})}
  function openForm(kind,item){
    const d=kind==='labor'?{name:item?item.name:'',hours:item?String(item.hours):'',rate:item?String(item.rate):''}
      :kind==='cost'?{name:item?item.name:'',amount:item?String(item.amount):''}
      :{name:kind==='plan-rename'&&item?item.name:''};
    go({view:'form',from:ui.view||'list',form:{kind:kind,id:kind==='labor'||kind==='cost'?(item?item.id:null):null},draft:d,err:'',delArm:false,menu:false,confirm:false});
  }
  function closeForm(){go({view:ui.from||'list',form:null,draft:null,err:'',delArm:false})}

  function dupPlan(p){
    const nid=uid();
    run(s=>{
      const L=Array.isArray(s&&s.plans)?s.plans:[];
      const src=L.find(x=>x.id===p.id)||p;
      const cp={id:nid,name:(src.name+' 副本').slice(0,40),
        labor:(src.labor||[]).map((x,i)=>Object.assign({},x,{id:nid+'-l'+i})),
        costs:(src.costs||[]).map((x,i)=>Object.assign({},x,{id:nid+'-c'+i}))};
      const at=L.findIndex(x=>x.id===p.id);
      return Object.assign({},s,{plans:at<0?L.concat([cp]):L.slice(0,at+1).concat([cp],L.slice(at+1))});
    },{view:'plan',planId:nid,menu:false,confirm:false});
  }
  function delPlan(p){
    run(s=>Object.assign({},s,{plans:(Array.isArray(s&&s.plans)?s.plans:[]).filter(x=>x.id!==p.id)}),{view:'list',planId:null,menu:false,confirm:false});
  }


  let errEl=null;
  const showErr=m=>{if(errEl)errEl.textContent=m?'⚠ '+m:''};
  function saveForm(){
    const f=ui.form||{},d=ui.draft||{},k=f.kind||'';
    const isPlan=k.indexOf('plan')===0;
    const name=String(d.name||'').trim().slice(0,40);
    if(!name){showErr(isPlan?'请填写方案名称。':'请填写名称。');return}
    const pid=ui.planId;
    const back={form:null,draft:null,delArm:false};
    if(k==='plan-new'){
      const id=uid();
      run(s=>Object.assign({},s,{plans:(Array.isArray(s&&s.plans)?s.plans:[]).concat([{id:id,name:name,labor:[],costs:[]}])}),Object.assign({view:'plan',planId:id},back));
      return;
    }
    if(k==='plan-rename'){
      run(s=>mapPlans(s,p=>p.id===pid?Object.assign({},p,{name:name}):p),Object.assign({view:'plan'},back));
      return;
    }
    const iid=f.id||uid();
    let item,key;
    if(k==='labor'){
      const h=parseNum(d.hours,100000),r=parseNum(d.rate,1000000);
      if(Number.isNaN(h)){showErr('预计小时请填写 0 以上的数字。');return}
      if(Number.isNaN(r)){showErr('时薪请填写 0 以上的数字（元/小时）。');return}
      item={id:iid,name:name,hours:h,rate:r};key='labor';
    }else{
      const a=parseNum(d.amount,1000000000);
      if(Number.isNaN(a)){showErr('金额请填写 0 以上的数字（元）。');return}
      item={id:iid,name:name,amount:a};key='costs';
    }
    run(s=>mapPlans(s,p=>{
      if(p.id!==pid)return p;
      const L=Array.isArray(p[key])?p[key]:[];
      const has=L.some(x=>x.id===iid);
      return Object.assign({},p,{[key]:has?L.map(x=>x.id===iid?item:x):L.concat([item])});
    }),Object.assign({view:'plan'},back));
  }
  function delItem(){
    const f=ui.form||{},pid=ui.planId,key=f.kind==='labor'?'labor':'costs';
    if(!ui.delArm){go({delArm:true});return}
    run(s=>mapPlans(s,p=>p.id!==pid?p:Object.assign({},p,{[key]:(Array.isArray(p[key])?p[key]:[]).filter(x=>x.id!==f.id)})),{view:'plan',form:null,draft:null,delArm:false});
  }

  function renderForm(){
    const f=ui.form||{kind:'plan-new'},d=ui.draft||(ui.draft={}),k=f.kind,editing=!!f.id;
    const isPlan=k.indexOf('plan')===0;
    const T={labor:editing?'编辑人工':'添加人工',cost:editing?'编辑直接成本':'添加直接成本','plan-new':'新建报价方案','plan-rename':'重命名方案'};
    const pv=el('b',{},'—');
    const upd=()=>{
      if(k==='labor'){
        const h=parseNum(d.hours,100000),r=parseNum(d.rate,1000000);
        pv.textContent=(Number.isNaN(h)||Number.isNaN(r))?'—':money(h*r);
      }
    };
    const field=(key,label,cls,attrs)=>el('label',{class:'q-fld '+cls},
      el('span',{class:'q-fl'},label),
      el('input',Object.assign({class:'q-in',type:'text',value:d[key]==null?'':String(d[key]),'aria-label':label,
        oninput:e=>{d[key]=e.target.value;upd()},
        onkeydown:e=>{if(e.key==='Enter'){e.preventDefault();saveForm()}}},attrs||{})));
    const nm=field('name',isPlan?'方案名称':(k==='labor'?'工作项':'成本项'),'q-nm',{maxlength:'40',placeholder:isPlan?'如：基础版':(k==='labor'?'如：UI 设计':'如：材料')});
    const num=(key,label,ph)=>field(key,label,'q-half',{type:'number',inputmode:'decimal',step:'any',min:'0',placeholder:ph});
    const fields=k==='labor'?[nm,num('hours','预计小时','如 8'),num('rate','时薪（元/小时）','如 300')]
      :(k==='cost'?[nm,num('amount','金额（元）','如 500')]:[nm]);
    errEl=el('div',{class:'q-ferr',role:'alert'},ui.err?'⚠ '+ui.err:'');
    upd();
    const pvBox=k==='labor'?el('div',{class:'q-pv'},el('span',{},'小计 = 小时 × 时薪'),pv):null;
    const del=(editing&&!isPlan)?el('button',{class:'q-btn'+(ui.delArm?' q-arm':''),type:'button',onclick:delItem},ui.delArm?'确认删除':'删除'):null;
    const saveLabel=k==='plan-new'?'创建方案':(k==='plan-rename'||editing?'保存':'添加');
    return el('div',{class:'q-root'},
      el('div',{class:'q-panel q-fm'},
        el('div',{class:'q-fh'},
          el('button',{class:'q-btn q-sm',type:'button','aria-label':'返回',onclick:closeForm},'‹ 返回'),
          el('div',{class:'q-ft'},T[k]||'')),
        el('div',{class:'q-fb'},...K(...fields,pvBox,errEl)),
        el('div',{class:'q-ff'},...K(el('button',{class:'q-btn q-pri q-grow',type:'button',onclick:saveForm},saveLabel),del))));
  }


  function hero(p,t){
    const amt=money(t.total);
    const menu=ui.menu?(ui.confirm
      ?el('div',{class:'q-menu'},el('span',{},'删除整个方案？'),
        el('button',{class:'q-gb',type:'button',onclick:()=>go({confirm:false})},'取消'),
        el('button',{class:'q-gb q-bold',type:'button',onclick:()=>delPlan(p)},'确认删除'))
      :el('div',{class:'q-menu'},
        el('button',{class:'q-gb',type:'button',onclick:()=>openForm('plan-rename',p)},'重命名'),
        el('button',{class:'q-gb',type:'button',onclick:()=>dupPlan(p)},'复制'),
        el('button',{class:'q-gb',type:'button',onclick:()=>go({confirm:true})},'删除'))):null;
    return el('div',{class:'q-hero'},...K(
      el('div',{class:'q-head'},...K(
        big?null:el('button',{class:'q-ib',type:'button','aria-label':'返回方案列表',onclick:toList},'‹'),
        el('div',{class:'q-pname',title:p.name},p.name),
        el('button',{class:'q-ib',type:'button','aria-label':'方案操作：重命名、复制、删除','aria-expanded':ui.menu?'true':'false',onclick:()=>go({menu:!ui.menu,confirm:false})},'⋯'))),
      menu,
      el('div',{class:'q-tot'},el('span',{class:'q-tlab'},'总报价 · 人民币'),el('span',{class:'q-tamt '+fitCls(amt)},amt)),
      el('div',{class:'q-subs'},el('span',{},'人工 '+money(t.labor)+' · '+hrs(t.hours)+' 小时'),el('span',{},'直接成本 '+money(t.cost)))));
  }
  function itemsPanel(p,t){
    const L=Array.isArray(p.labor)?p.labor:[],C=Array.isArray(p.costs)?p.costs:[];
    const kids=[];
    if(!L.length&&!C.length)kids.push(el('div',{class:'q-hint'},'还没有明细。用下方按钮添加人工（小时 × 时薪）或直接成本。'));
    if(L.length){
      kids.push(el('div',{class:'q-sec'},el('span',{},'人工 · '+hrs(t.hours)+' 小时'),el('b',{},money(t.labor))));
      L.forEach(x=>kids.push(el('button',{class:'q-row',type:'button','aria-label':'编辑人工：'+x.name,onclick:()=>openForm('labor',x)},
        el('span',{class:'q-rn'},x.name),
        el('span',{class:'q-ra'},money(laborC(x)/100)),
        el('span',{class:'q-rm'},hrs(x.hours)+' 小时 × '+money(x.rate)+'/小时'))));
    }
    if(C.length){
      kids.push(el('div',{class:'q-sec'},el('span',{},'直接成本'),el('b',{},money(t.cost))));
      C.forEach(x=>kids.push(el('button',{class:'q-row',type:'button','aria-label':'编辑直接成本：'+x.name,onclick:()=>openForm('cost',x)},
        el('span',{class:'q-rn'},x.name),
        el('span',{class:'q-ra'},money(costC(x)/100)))));
    }
    return el('div',{class:'q-items q-panel'},...kids);
  }
  function addbar(){
    return el('div',{class:'q-add'},
